+});
+
+const KEYS = new Set(['port', 'host', 'retries', 'logLevel']);
+const LOG_LEVELS = new Set(['debug', 'info', 'warn', 'error']);
+
+function invalid(message) {
+  throw new Error(`Invalid configuration${message ? `: ${message}` : ''}`);
+}
+
+function parseConfig(text) {
+  if (typeof text !== 'string') {
+    invalid('input must be a JSON string');
+  }
+
+  let parsed;
+  try {
+    parsed = JSON.parse(text);
+  } catch {
+    invalid('input is not valid JSON');
+  }
+
+  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
+    invalid('top level must be an object');
+  }
+
+  for (const key of Object.keys(parsed)) {
+    if (!KEYS.has(key)) {
+      invalid(`unknown key "${key}"`);
+    }
+  }
