'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { parseConfig } = require('./config.cjs');

test('parses a complete valid configuration', () => {
  assert.deepStrictEqual(parseConfig('{"port":8080,"host":"example.test","retries":4,"logLevel":"debug"}'), {
    port: 8080,
    host: 'example.test',
    retries: 4,
    logLevel: 'debug'
  });
});

test('applies defaults for omitted fields', () => {
  assert.deepStrictEqual(parseConfig('{}'), {
    port: 3000,
    host: '127.0.0.1',
    retries: 2,
    logLevel: 'info'
  });
});

test('returns a fresh result object', () => {
  const first = parseConfig('{}');
  first.port = 1;
  assert.deepStrictEqual(parseConfig('{}'), {
    port: 3000,
    host: '127.0.0.1',
    retries: 2,
    logLevel: 'info'
  });
});

test('accepts boundary values', () => {
  assert.deepStrictEqual(parseConfig(JSON.stringify({
    port: 1, host: 'a'.repeat(253), retries: 0, logLevel: 'error'
  })), {
    port: 1, host: 'a'.repeat(253), retries: 0, logLevel: 'error'
  });
  assert.equal(parseConfig('{"port":65535,"retries":10}').port, 65535);
});

test('rejects malformed input and invalid top-level values', () => {
  for (const value of [undefined, null, 42, '{} trailing', 'null', '[]', '"text"']) {
    assert.throws(() => parseConfig(value), Error);
  }
});

test('rejects unknown keys and explicit nulls', () => {
  assert.throws(() => parseConfig('{"extra":true}'), Error);
  for (const key of ['port', 'host', 'retries', 'logLevel']) {
    assert.throws(() => parseConfig(JSON.stringify({ [key]: null })), Error);
  }
});

test('rejects incorrect types, fractional values, and out-of-range values', () => {
  for (const value of [0, 65536, 1.5, '3000', true]) {
    assert.throws(() => parseConfig(JSON.stringify({ port: value })), Error);
  }
  for (const value of [-1, 11, 1.2, '2', false]) {
    assert.throws(() => parseConfig(JSON.stringify({ retries: value })), Error);
  }
  for (const value of ['', 'a'.repeat(254), 'has space', 'has\ttab', 123]) {
    assert.throws(() => parseConfig(JSON.stringify({ host: value })), Error);
  }
  for (const value of ['trace', '', 1, true]) {
    assert.throws(() => parseConfig(JSON.stringify({ logLevel: value })), Error);
  }
});
